\title{%
Scalar–Angular–Twist Prediction of a\\
\large{Measurable Phase Retardance from a Single Angular Kink}}

\author[1]{Nathan McKnight}
\author[2]{Validation Lab 1 Collaboration\thanks{Contact: validation-lab@sat-project.org}}
