\begin{document}
\maketitle

\begin{abstract}
Within the Scalar–Angular–Twist (SAT) framework a local ``kink'' in the scalar
misalignment field $\theta_{4}(x)$ produces a smooth modulation of the
refractive index
$\Delta n(x)=\eta\sin^{2}\!\theta_{4}(x)$.
Numerical integration for a realistic parameter set
($\mu=\SI{5}{\micro\metre^{-1}}$, $\eta=0.02$, $\lambda=\SI{650}{\nano\metre}$)
predicts a total optical phase delay
$\Delta\phi\simeq1.48\;\mathrm{rad}$ across a \SI{20}{\micro\metre} path—
well above interferometric detection thresholds.
We supply reproducible \textsc{Python} code, the resulting
refractive‐index profile, and an SAT–independent classical‐optics
interpretation suitable for immediate laboratory testing.
\end{abstract}

\section{SAT Motivation (specialist)}
SAT posits a scalar angular misalignment field $\theta_{4}(x)$ whose spatial
gradients encode inertial and optical phenomena.
A topological domain wall is modeled by
\begin{equation}
\theta_{4}(x)=\frac{2\pi}{3}\,
\frac{1+\tanh\!\bigl(\mu x\bigr)}{2},
\end{equation}
linking adjacent $Z_{3}$ vacuum sectors.
Photon propagation couples to $\theta_{4}$ through the effective
index shift
\begin{equation}
\Delta n(x)=\eta\sin^{2}\theta_{4}(x).
\end{equation}
The accumulated phase for wavelength $\lambda$ is
\(
\Delta\phi=(2\pi/\lambda)\int \Delta n(x)\,dx.
\)

\section{Numerical Procedure}
\paragraph{Parameters}
\begin{center}
\begin{tabular}{lcl}
Wall steepness & $\mu$ & \SI{5}{\micro\metre^{-1}} \\
Index amplitude & $\eta$ & 0.02 \\
Wavelength & $\lambda$ & \SI{650}{\nano\metre} \\
Domain & $x$ & $[-10,10]\,\si{\micro\metre}$ \\
Grid & $N$ & 1000 points \\
\end{tabular}
\end{center}

\paragraph{Code (Python 3)}
\begin{minted}[fontsize=\small]{python}
import numpy as np
mu     = 5          # μm⁻¹
eta    = 0.02
lam    = 650e-3     # μm
x      = np.linspace(-10, 10, 1000)
theta4 = (2*np.pi/3)*(1 + np.tanh(mu*x))/2
deltan = eta * np.sin(theta4)**2
dphi   = 2*np.pi/lam * np.trapz(deltan, x)
print(dphi)  # → 1.475 rad
\end{minted}

